 "content": "def transform(grid):
    h, w = len(grid), len(grid[0])
    sep_rows = [r for r in range(h) if len(set(grid[r])) == 1]
    sep_cols = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    def ranges(length, cuts):
        out, start = [], 0
        for cut in cuts:
            if start < cut:
                out.append((start, cut))
            start = cut + 1
        if start < length:
            out.append((start, length))
        return out

    row_regions = ranges(h, sep_rows)
    col_regions = ranges(w, sep_cols)
    result = []
    for r0, r1 in row_regions:
        row = []
        for c0, c1 in col_regions:
            vals = [grid[r][c] for r in range(r0, r1) for c in range(c0, c1)]
            counts = {v: vals.count(v) for v in set(vals)}
            background = max(counts, key=counts.get)
            marks = sum(1 for v in vals if v != background)
            row.append(1 if marks == 2 else background)
        result.append(row)
    return result
